@@ -0,0 +1,112 @@
+import { flushPromises, mount, type VueWrapper } from "@vue/test-utils";
+import { afterEach, beforeEach, describe, expect, test, vi } from "vitest";
+import GroupAIProviderDialog from "./GroupAIProviderDialog.vue";
+
+type Deferred = { resolve: (v: unknown) => void };
+const pending: Record<string, Deferred> = {};
+const getOne = vi.fn((id: string) => new Promise((resolve) => {
+  pending[id] = { resolve };
+}));
+
+vi.mock("~/composables/use-ai-providers", () => ({
+  useAIProviders: () => ({
+    loading: ref(false),
+    getOne,
+    testOne: vi.fn(),
+    testSavedOne: vi.fn(),
+  }),
+}));
+
+function provider(name: string) {
+  return { data: { name, model: `${name}-model`, baseUrl: null, timeout: 30, requestHeaders: {}, requestParams: {} } };
+}
+
+const wrappers: VueWrapper[] = [];
+
+function mountDialog(props: { modelValue: boolean; providerId?: string }) {
+  const wrapper = mount(GroupAIProviderDialog, {
+    props,
+    global: {
+      directives: { "no-autofill": {} },
+      mocks: { $globals: { icons: {} } },
+      stubs: {
+        BaseDialog: { template: "<div><slot /></div>" },
+        AppLoader: { template: "<div class=\"loader\" />" },
+        BaseKeyValueEditor: true,
+        VCardText: { template: "<div class=\"form\"><slot /></div>" },
+        VForm: { template: "<form><slot /></form>" },
+        VBtn: true,
+        VAlert: true,
+        VDivider: true,
+        VExpansionPanels: true,
+        VNumberInput: true,
+        VTextField: {
+          props: ["modelValue", "label"],
+          template: "<input :data-label=\"label\" :value=\"modelValue\">",
+        },
+      },
+    },
+  });
+  wrappers.push(wrapper);
+  return wrapper;
+}
+
+const nameValue = (w: VueWrapper) => (w.find("input[data-label='Provider Name']").element as HTMLInputElement).value;
+const formShown = (w: VueWrapper) => w.find(".form").exists();
+
+describe("GroupAIProviderDialog stale getOne", () => {
+  beforeEach(() => {
+    vi.stubGlobal("useNuxtApp", () => ({ $globals: { icons: {} } }));
+    getOne.mockClear();
+    Object.keys(pending).forEach(k => delete pending[k]);
+  });
+  afterEach(() => {
+    wrappers.forEach(w => w.unmount());
+    wrappers.length = 0;
+  });
+
+  test("provider switch A->B: late answer for A is ignored", async () => {
+    const w = mountDialog({ modelValue: true, providerId: "A" });
+    await w.setProps({ providerId: "B" });
+    pending.B!.resolve(provider("B"));
+    await flushPromises();
+    expect(nameValue(w)).toBe("B");
+    pending.A!.resolve(provider("A"));
+    await flushPromises();
+    expect(nameValue(w)).toBe("B");
+  });
+
+  test("provider switch A->B: late A must not reveal the form while B is pending", async () => {
+    const w = mountDialog({ modelValue: true, providerId: "A" });
+    await w.setProps({ providerId: "B" });
+    pending.A!.resolve(provider("A"));
+    await flushPromises();
+    expect(formShown(w)).toBe(false);
+  });
+
+  test("close before answer, then reopen: old answer is ignored", async () => {
+    const w = mountDialog({ modelValue: true, providerId: "A" });
+    await w.setProps({ modelValue: false });
+    pending.A!.resolve(provider("A"));
+    await flushPromises();
+    expect(formShown(w)).toBe(false);
+    await w.setProps({ modelValue: true });
+    expect(formShown(w)).toBe(false);
+  });
+
+  test("edit->create with late A: form stays empty", async () => {
+    const w = mountDialog({ modelValue: true, providerId: "A" });
+    await w.setProps({ providerId: undefined });
+    expect(formShown(w)).toBe(true);
+    pending.A!.resolve(provider("A"));
+    await flushPromises();
+    expect(nameValue(w)).toBe("");
+  });
+
+  test("current answer still fills the form", async () => {
+    const w = mountDialog({ modelValue: true, providerId: "A" });
+    pending.A!.resolve(provider("A"));
+    await flushPromises();
+    expect(nameValue(w)).toBe("A");
+  });
+});
