diff --git a/frontend/app/components/Domain/Group/GroupAIProviderDialog.test.ts b/frontend/app/components/Domain/Group/GroupAIProviderDialog.test.ts
new file mode 100644
index 0000000..3ba1fb3
--- /dev/null
+++ b/frontend/app/components/Domain/Group/GroupAIProviderDialog.test.ts
@@ -0,0 +1,144 @@
+import { flushPromises, mount, type VueWrapper } from "@vue/test-utils";
+import { afterEach, beforeEach, describe, expect, test, vi } from "vitest";
+import GroupAIProviderDialog from "./GroupAIProviderDialog.vue";
+
+type Provider = { name: string; model: string; baseUrl?: string | null; timeout?: number };
+type Deferred = { promise: Promise<{ data: Provider | null }>; resolve: (p: Provider | null) => void };
+
+function deferred(): Deferred {
+  let resolve!: (p: Provider | null) => void;
+  const promise = new Promise<{ data: Provider | null }>((res) => {
+    resolve = p => res({ data: p });
+  });
+  return { promise, resolve };
+}
+
+const pending: Record<string, Deferred> = {};
+const getOne = vi.fn((id: string) => {
+  pending[id] = deferred();
+  return pending[id].promise;
+});
+
+vi.mock("~/composables/use-ai-providers", async () => {
+  const { ref } = await import("vue");
+  return {
+    useAIProviders: () => ({
+      loading: ref(false),
+      getOne,
+      testOne: vi.fn(),
+      testSavedOne: vi.fn(),
+    }),
+  };
+});
+
+const providerA: Provider = { name: "Provider A", model: "model-a" };
+const providerB: Provider = { name: "Provider B", model: "model-b" };
+
+const wrappers: VueWrapper[] = [];
+
+function mountDialog(props: { modelValue: boolean; providerId?: string }) {
+  const wrapper = mount(GroupAIProviderDialog, {
+    props,
+    global: {
+      mocks: { $globals: { icons: {} } },
+      directives: { "no-autofill": {} },
+      stubs: {
+        BaseDialog: { template: "<div><slot /></div>" },
+        BaseKeyValueEditor: true,
+        AppLoader: { template: "<div class=\"loader\" />" },
+        VCardText: { template: "<div><slot /></div>" },
+        VForm: { template: "<form><slot /></form>" },
+        VBtn: { template: "<button><slot /></button>" },
+        VAlert: { template: "<div><slot /></div>" },
+        VNumberInput: true,
+        VExpansionPanels: true,
+        VTextField: {
+          props: ["modelValue", "label"],
+          template: "<input :value=\"modelValue\" :aria-label=\"label\">",
+        },
+      },
+    },
+  });
+  wrappers.push(wrapper);
+  return wrapper;
+}
+
+function nameValue(wrapper: VueWrapper): string | undefined {
+  const input = wrapper.find("input");
+  return input.exists() ? (input.element as HTMLInputElement).value : undefined;
+}
+
+describe("GroupAIProviderDialog stale provider fetch", () => {
+  beforeEach(() => {
+    getOne.mockClear();
+    Object.keys(pending).forEach(key => Reflect.deleteProperty(pending, key));
+    vi.stubGlobal("useNuxtApp", () => ({ $globals: { icons: {} } }));
+  });
+
+  afterEach(() => {
+    wrappers.splice(0).forEach(w => w.unmount());
+    vi.unstubAllGlobals();
+  });
+
+  test("switching A to B ignores A when A resolves after B", async () => {
+    const wrapper = mountDialog({ modelValue: true, providerId: "A" });
+    await flushPromises();
+    await wrapper.setProps({ providerId: "B" });
+    await flushPromises();
+
+    pending.B!.resolve(providerB);
+    await flushPromises();
+    expect(nameValue(wrapper)).toBe("Provider B");
+
+    pending.A!.resolve(providerA);
+    await flushPromises();
+    expect(nameValue(wrapper)).toBe("Provider B");
+  });
+
+  test("close then open B ignores a late answer for A", async () => {
+    const wrapper = mountDialog({ modelValue: true, providerId: "A" });
+    await flushPromises();
+    await wrapper.setProps({ modelValue: false });
+    await flushPromises();
+    await wrapper.setProps({ modelValue: true, providerId: "B" });
+    await flushPromises();
+
+    pending.B!.resolve(providerB);
+    await flushPromises();
+    pending.A!.resolve(providerA);
+    await flushPromises();
+
+    expect(nameValue(wrapper)).toBe("Provider B");
+  });
+
+  test("a late answer for A after close does not fill the form or end loading", async () => {
+    const wrapper = mountDialog({ modelValue: true, providerId: "A" });
+    await flushPromises();
+    await wrapper.setProps({ modelValue: false });
+    await flushPromises();
+    await wrapper.setProps({ modelValue: true, providerId: "B" });
+    await flushPromises();
+
+    pending.A!.resolve(providerA);
+    await flushPromises();
+
+    // B is still pending: the form must not have been shown with A's data
+    expect(wrapper.find(".loader").exists()).toBe(true);
+    expect(nameValue(wrapper)).toBeUndefined();
+  });
+
+  test("the latest answer still fills the form", async () => {
+    const wrapper = mountDialog({ modelValue: true, providerId: "A" });
+    await flushPromises();
+    pending.A!.resolve(providerA);
+    await flushPromises();
+    expect(nameValue(wrapper)).toBe("Provider A");
+  });
+
+  test("create mode shows the empty form without fetching", async () => {
+    const wrapper = mountDialog({ modelValue: true });
+    await flushPromises();
+    expect(getOne).not.toHaveBeenCalled();
+    expect(nameValue(wrapper)).toBe("");
+  });
+});
