+'use strict';
+
+const FORMAT = /^(\d{4})-(\d{2})-(\d{2})$/;
+const DAYS = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
+
+// Strict calendar-date check for YYYY-MM-DD. Integer arithmetic only: Date
+// normalises overflowing days and mishandles years 0 to 99.
+function isValidDate(s) {
+  if (typeof s !== 'string') return false;
+  // [0-9] (not \d) is implied: JS \d without the u/v flag is ASCII-only.
+  const m = FORMAT.exec(s);
+  if (!m) return false;
+  const year = Number(m[1]);
+  const month = Number(m[2]);
+  const day = Number(m[3]);
+  if (year < 1 || month < 1 || month > 12 || day < 1) return false;
+  const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
+  const max = month === 2 && leap ? 29 : DAYS[month - 1];
+  return day <= max;
+}
+
+module.exports = { isValidDate };
