diff --git a/test/dates.test.js b/test/dates.test.js
new file mode 100644
index 0000000..116ee8c
--- /dev/null
+++ b/test/dates.test.js
@@ -0,0 +1,42 @@
+'use strict';
+
+const test = require('node:test');
+const assert = require('node:assert/strict');
+const { isValidDate } = require('../src/dates');
+
+test('accepts real calendar dates incl. leap days and range ends', () => {
+  for (const d of [
+    '2024-02-29', '2000-02-29', '0001-01-01', '9999-12-31', '2026-01-31', '2026-04-30',
+    '2026-12-31', '0004-02-29', '2026-02-28',
+  ]) {
+    assert.equal(isValidDate(d), true, d);
+  }
+});
+
+test('rejects impossible calendar dates', () => {
+  for (const d of [
+    '2026-02-30', '2025-02-29', '1900-02-29', '2026-04-31', '2026-00-10', '2026-13-01',
+    '2026-01-00', '0000-01-01', '2026-01-32', '2026-06-31', '2100-02-29',
+  ]) {
+    assert.equal(isValidDate(d), false, d);
+  }
+});
+
+test('rejects wrong formats without trimming or normalising', () => {
+  for (const d of [
+    '2026-1-1', '2026-01-1', '26-01-01', '20260101', '2026/01/01', ' 2026-01-01', '2026-01-01 ',
+    '2026-01-01\n', '\n2026-01-01', '2026-01-01T00:00:00Z', '2026-01-01T', '12026-01-01',
+    '2026-001-01', '', ' ', '+026-01-01', '-001-01-01', "2026-01-01'; DROP TABLE pantry;--",
+    '２０２６-01-01',
+    '٢٠٢٦-01-01', // Arabic-Indic digits
+  ]) {
+    assert.equal(isValidDate(d), false, JSON.stringify(d));
+  }
+});
+
+test('rejects non-strings without coercion', () => {
+  const stringish = { toString: () => '2026-01-01' };
+  for (const v of [null, undefined, 20260101, 2026, true, {}, [], ['2026-01-01'], stringish, new Date(), NaN]) {
+    assert.equal(isValidDate(v), false, String(typeof v));
+  }
+});
