+  // a dated insert for an existing food and kind is a second lot
+  db.prepare("INSERT INTO pantry(food, kind, expires_on, quantity) VALUES ('flour','mass','2026-05-05',10)").run();
+  assert.equal(db.prepare("SELECT count(*) c FROM pantry WHERE food='flour'").get().c, 2);
+  assert.deepEqual(migrate(db, SHIPPED), []);
+  db.close();
+});
