+test('upgraded database serves old rows through the API with expiresOn null', async () => {
+  const file = path.join(tmp, 'upgrade-api.db');
+  const old = openDb(file);
+  migrate(old, only001());
+  old.prepare('INSERT INTO pantry(food, kind, quantity) VALUES (?, ?, ?)').run('flour', 'mass', 1100);
+  old.prepare('INSERT INTO pantry(food, kind, quantity) VALUES (?, ?, ?)').run('egg', 'count', 3);
+  old.close();
+
+  const app = await startApp({ dbPath: file });
+  try {
+    const r = await http('GET', app.url + '/pantry');
+    assert.equal(r.status, 200);
+    assert.deepEqual(r.json.items, [
+      { food: 'egg', quantity: 3, unit: null, expiresOn: null },
+      { food: 'flour', quantity: 1.1, unit: 'kg', expiresOn: null },
+    ]);
+    const add = await http('POST', app.url + '/pantry/items', {
+      food: 'flour', quantity: 100, unit: 'g', expiresOn: '2026-05-05',
+    });
+    assert.equal(add.status, 201);
+    const again = await http('GET', app.url + '/pantry');
+    assert.deepEqual(again.json.items.find((i) => i.food === 'flour'), {
+      food: 'flour', quantity: 1.2, unit: 'kg', expiresOn: '2026-05-05',
+    });
+  } finally {
+    await app.close();
+  }
+});
